declarations.TSCallable:
public class TSCallable implements System.Callable {
 public Integer calls=0;
 public Object call(String action, Map<String,Object> args){
  calls++;
  if(action=='echo'){return args.get('value');}
  if(action=='size'){return args.size();}
  if(action=='null'){return null;}
  if(action=='mutate'){args.put('seen',true);return args.get('seen');}
  if(action=='fail'){throw new TSFailureException('call failed');}
  throw new TSFailureException('unknown action');
 }
}

